DROP VIEW "private"."v_water_tanker_request";--> statement-breakpoint
CREATE VIEW "private"."v_water_tanker_request" AS (select "users"."house", "private"."water_tanker_request_list"."name" as "list", "private"."water_tanker_request"."request_status", "private"."water_tanker_request"."uuid" from "private"."water_tanker_request" inner join "private"."water_tanker_request_list" on "private"."water_tanker_request"."water_tanker_request_list_id" = "private"."water_tanker_request_list"."id" inner join "users" on "private"."water_tanker_request"."user_id" = "users"."id" where ("private"."water_tanker_request"."is_active" = true and ("private"."water_tanker_request"."request_status" = 'pending' or "private"."water_tanker_request"."updated_at" between now() - interval '2 hours' and now())) order by "private"."water_tanker_request"."created_at" asc);